#!/usr/bin/env bash
# Verify that a published catalog can be imported with `docker mcp catalog pull`.
#
# Usage: verify-catalog-pull.sh <oci-reference> <expected-artifact.json>
#
# <expected-artifact.json> is the payload generated by
# `mcp-catalog docker catalog --artifact`; the pulled catalog must contain its title and
# every server name in it.
set -euo pipefail

if [ "$#" -ne 2 ]; then
  echo "usage: $0 <oci-reference> <expected-artifact.json>" >&2
  exit 2
fi
reference="$1"
expected="$2"
pulled="$(mktemp)"
trap 'rm -f "$pulled"' EXIT

docker mcp catalog pull "$reference"
docker mcp catalog show "$reference" --format json >"$pulled"

python3 -I - "$expected" "$pulled" <<'PY'
import json
import sys

expected = json.load(open(sys.argv[1], encoding='utf-8'))
pulled = open(sys.argv[2], encoding='utf-8').read()

missing = [expected['title']] if expected['title'] not in pulled else []
missing += [
    server['snapshot']['server']['name']
    for server in expected['servers']
    if f'"{server["snapshot"]["server"]["name"]}"' not in pulled
]
if missing:
    print(f'Pulled catalog is missing: {", ".join(missing)}', file=sys.stderr)
    sys.exit(1)
print(f'Pulled catalog contains {len(expected["servers"])} expected server(s).')
PY
